fn empty(n: u8) -> Vec<f64> {
    // Pre-allocate exactly n elements to avoid reallocations.
    let mut result = Vec::with_capacity(n as usize);
    // Iteratively push zeros until we reach the desired length.
    for _ in 0..n {
        result.push(0.0);
    }
    result
}

